function expandDefinition(item) {
  const [
    id,
    synsetId,
    partOfSpeech,
    partOfSpeechLabel,
    lexicalFile,
    definition,
    source,
    meaningZh,
    translationStatus,
  ] = item;

  return {
    id,
    synsetId,
    partOfSpeech,
    partOfSpeechLabel,
    lexicalFile,
    definition,
    source,
    meaningZh,
    translationStatus,
  };
}

export function getWordDefinitions(wordId) {
  const definitions =
    WORD_DEFINITIONS_BY_ID[String(wordId)];

  if (!definitions) {
    return null;
  }

  return {
    definitions:
      definitions.map(
        expandDefinition
      ),
  };
}
